import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.Boholvbs.js";const m=JSON.parse(`{"title":"Custom slash commands","description":"Markdown commands for prioricode's slash palette — arguments ($1, $ARGUMENTS), embedded shell output, per-command model and agent, built-in /init and /review.","frontmatter":{"title":"Custom slash commands","description":"Markdown commands for prioricode's slash palette — arguments ($1, $ARGUMENTS), embedded shell output, per-command model and agent, built-in /init and /review."},"headers":[],"relativePath":"extending/commands.md","filePath":"extending/commands.md"}`),n={name:"extending/commands.md"};function o(d,e,l,r,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<p>You type <code>/deploy staging</code>. PrioriCode expands a markdown template — with arguments slotted in and live shell output baked in — and sends it as a prompt. Custom commands are prompt macros: your team&#39;s repeated asks, named.</p><h2 id="the-file" tabindex="-1">The file <a class="header-anchor" href="#the-file" aria-label="Permalink to &quot;The file&quot;">​</a></h2><p>Drop markdown into <code>.prioricode/commands/</code> (project) or <code>~/.config/prioricode/commands/</code> (global) — both <code>command/</code> and <code>commands/</code> work, subfolders are fine, and the path becomes the command name (<code>git/commit.md</code> → <code>/commit</code> from that folder&#39;s scan root).</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Summarize a branch&#39;s changes against main</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model: anthropic/claude-sonnet-4-5</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">agent: plan</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Summarize what </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`$1`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> changes relative to </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`main`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current diff stat:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`git diff main...$1 --stat`</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cover: features added, risks, and anything that looks accidentally included.</span></span></code></pre></div><p><code>/branch-summary feature/auth</code> then arrives as a fully-realized prompt.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Behavior</th></tr></thead><tbody><tr><td><code>$1</code>, <code>$2</code>, …</td><td>Positional arguments, split on whitespace (quote with <code>&quot;…&quot;</code>/<code>&#39;…&#39;</code> to group). The <strong>highest-numbered</strong> placeholder swallows the rest — <code>$3</code> in a two-<code>$</code> template gets everything after arg 2.</td></tr><tr><td><code>$ARGUMENTS</code></td><td>The raw argument string, verbatim.</td></tr><tr><td><em>(neither present)</em></td><td>Your arguments are appended after the template, separated by a blank line.</td></tr></tbody></table><p>The palette shows the placeholders each command expects (they&#39;re harvested from the template), so <code>/deploy</code> tells you it wants <code>$1 $2</code> before you guess.</p><h2 id="shell-interpolation" tabindex="-1"><code>!`shell` </code> interpolation <a class="header-anchor" href="#shell-interpolation" aria-label="Permalink to &quot;``!`shell` `` interpolation&quot;">​</a></h2><p>Backtick expressions of the form <code>!`command` </code> run <strong>before</strong> the prompt is sent, and their stdout replaces them — the model sees the output, not the command. It&#39;s the difference between &quot;check the test failures&quot; and a prompt that already contains them:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Triage the latest failing tests</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Here&#39;s what broke:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`bun test 2&gt;&amp;1 | tail -50`</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rank by severity and start with any that touch </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`src/billing/`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div><p>Shell commands run in your config <code>shell</code> (or <code>$SHELL</code>). This is prompt-time execution, so: keep it deterministic, keep it fast, and never write secrets into the output you&#39;re pasting into a session.</p><h2 id="frontmatter-fields" tabindex="-1">Frontmatter fields <a class="header-anchor" href="#frontmatter-fields" aria-label="Permalink to &quot;Frontmatter fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Effect</th></tr></thead><tbody><tr><td><code>description</code></td><td>Shown in autocomplete</td></tr><tr><td><code>agent</code></td><td>Run as this agent (its model/permissions apply)</td></tr><tr><td><code>model</code></td><td>Override model for this command, <code>provider/model</code></td></tr><tr><td><code>variant</code></td><td>Model variant (reasoning effort)</td></tr><tr><td><code>subtask</code></td><td><code>true</code> → dispatch as a subagent task instead of steering the session</td></tr></tbody></table><h2 id="from-the-cli" tabindex="-1">From the CLI <a class="header-anchor" href="#from-the-cli" aria-label="Permalink to &quot;From the CLI&quot;">​</a></h2><p>Commands are first-class in headless mode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch-summary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/auth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;extra, quoted args work too&quot;</span></span></code></pre></div><p>That&#39;s what makes them CI-legitimate: a reviewed, versioned prompt template with argument hygiene, callable from a pipeline.</p><h2 id="built-right-alongside-your-own" tabindex="-1">Built right alongside your own <a class="header-anchor" href="#built-right-alongside-your-own" aria-label="Permalink to &quot;Built right alongside your own&quot;">​</a></h2><p>Two ship with the binary:</p><ul><li><strong><code>/init</code></strong> — guided <code>AGENTS.md</code> setup: PrioriCode studies the project and walks you into a good context file. The fastest way to bootstrap <a href="./../using/context.html">project context</a>.</li><li><strong><code>/review</code></strong> — review changes (commit, branch, or PR; defaults to uncommitted) as a subtask.</li></ul><p><a href="./skills.html">Skills</a> also surface as commands, and remote MCP servers expose their prompts as <code>/name:mcp</code> entries — autocomplete labels the difference.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./skills.html">Skills</a> — Procedures chosen by the agent instead of typed by you. <ul><li><a href="./../using/agents.html">Agents</a> — The <code>agent</code>/<code>model</code> fields point at these.</li><li><a href="./../using/headless.html">Headless</a> — <code>run --command</code> in pipelines.</li><li><a href="./../reference/slash-commands.html">Slash-command reference</a> — The full built-in list.</li></ul></li></ul>',24)])])}const k=t(n,[["render",o]]);export{m as __pageData,k as default};
